void setup() {
 Serial.begin(115200);
 Wire.begin(); // Wake MPU6500                          Code Explanation
 Wire.beginTransmission(MPU_ADDR);             ― Wire.begin() → Starts I²C
 Wire.write(0x6B);
 Wire.write(0x00);                                      communication
 Wire.endTransmission(true);                ― Outputs tilt angle data for robot delay(2000); // keep leg straight
 offset = readTilt(); // Calibrate zero position                          balance and navigation
 Serial.println("Calibration done!");}
void loop() {
 tiltAngle = readTilt() - offset;
 Serial.print("Lower leg tilt: "); Serial.print(tiltAngle); Serial.println(" degrees");
 delay(50);}
float readTilt() {
 readAccel(); // Pitch angle (forward/backward)
 float angle = atan2(-ax, sqrt((float)ay * ay + (float)az * az));
 return angle * 180.0 / PI;}
void readAccel() {
 Wire.beginTransmission(MPU_ADDR); Wire.write(0x3B);
 Wire.endTransmission(false);
 Wire.requestFrom(MPU_ADDR, 6, true);
 ax = Wire.read() << 8 | Wire.read(); ay = Wire.read() << 8 | Wire.read();
 az = Wire.read() << 8 | Wire.read();}


